function getTripCityGeo() {
  try {
    const cached = localStorage.getItem("taxusa_cached_trip");
    if (!cached) return null;
    const trip = JSON.parse(cached);
    const dest = (trip.destination || "").toLowerCase().trim();
    for (const key of Object.keys(CITY_GEO)) {
      if (dest.includes(key) || key.includes(dest)) return {
        city: key,
        ...CITY_GEO[key]
      };
    }
    return {
      city: dest,
      viewbox: null,
      state: "FL"
    };
  } catch (e) {
    return null;
  }
}

function parseNominatimResult(item) {
  const a = item.address || {};
  let name = item.name || "";
  if (!name && a.road) name = (a.house_number ? a.house_number + " " : "") + a.road;
  if (!name) name = item.display_name.split(",")[0];
  const parts = [];
  if (a.road && item.name) parts.push((a.house_number ? a.house_number + " " : "") + a.road);
  if (a.city || a.town || a.village) parts.push(a.city || a.town || a.village);
  if (a.state) parts.push(a.state);
  const sub = parts.join(", ");
  const addrParts = [];
  if (a.house_number) addrParts.push(a.house_number);
  if (a.road) addrParts.push(a.road);
  if (a.city || a.town || a.village) addrParts.push(a.city || a.town || a.village);
  if (a.state) addrParts.push(a.state);
  const address = addrParts.length >= 2 ? addrParts.join(", ") : item.display_name.split(",").slice(0, 3).join(",").trim();
  return {
    name: name,
    sub: sub || address,
    address: address,
    lat: item.lat,
    lon: item.lon,
    type: item.type,
    mapsUrl: `https://www.google.com/maps/search/?api=1&query=${item.lat},${item.lon}`
  };
}

async function searchAddress(query) {
  if (!query || query.length < 3) return [];
  try {
    const lang = localStorage.getItem("appLang") || "es";
    const base = `https://nominatim.openstreetmap.org/search?format=json&limit=6&countrycodes=us&addressdetails=1&accept-language=${lang}`;
    const hasState = /\b([A-Z]{2}|florida|california|texas|new york|nevada|illinois|georgia|massachusetts|colorado)\b/i.test(query);
    const hasCountry = /\b(usa|united states|estados unidos)\b/i.test(query);
    const hasCity = /\b(orlando|kissimmee|miami|tampa|chicago|houston|boston|denver|atlanta|las vegas)\b/i.test(query);
    const alreadyComplete = hasState || hasCountry || hasCity;
    const tripGeo = getTripCityGeo();
    let q = query;
    if (!alreadyComplete && tripGeo) {
      q = tripGeo.state ? `${query}, ${tripGeo.city ? tripGeo.city.charAt(0).toUpperCase() + tripGeo.city.slice(1) : ""}, ${tripGeo.state}, USA` : `${query}, USA`;
    } else if (!alreadyComplete) {
      q = `${query}, FL, USA`;
    }
    let data = [];
    if (tripGeo?.viewbox) {
      const res1 = await fetch(`${base}&q=${encodeURIComponent(q)}&viewbox=${tripGeo.viewbox}&bounded=1`, {
        headers: {
          "Accept-Language": lang
        }
      });
      if (res1.ok) data = await res1.json();
    }
    if (!data.length) {
      const res2 = await fetch(`${base}&q=${encodeURIComponent(q)}`, {
        headers: {
          "Accept-Language": lang
        }
      });
      if (res2.ok) data = await res2.json();
    }
    if (!data.length && q !== query) {
      const res3 = await fetch(`${base}&q=${encodeURIComponent(query)}`, {
        headers: {
          "Accept-Language": lang
        }
      });
      if (res3.ok) data = await res3.json();
    }
    return data.map(parseNominatimResult);
  } catch (e) {
    return [];
  }
}

function renderAcList(listEl, items, onSelect, focusedIdx) {
  listEl.innerHTML = "";
  if (!items.length) {
    listEl.classList.remove("show");
    return;
  }
  items.forEach((item, i) => {
    const div = document.createElement("div");
    div.className = "autocomplete-item" + (i === focusedIdx ? " focused" : "");
    div.setAttribute("role", "option");
    const icon = getAddressIcon(item.type);
    div.innerHTML = `<span class="ac-icon">${icon}</span><div class="ac-body"><div class="ac-main">${escHtml(item.name)}</div><div class="ac-sub">${escHtml(item.sub)}</div></div>`;
    div.addEventListener("mousedown", e => {
      e.preventDefault();
      onSelect(item);
    });
    listEl.appendChild(div);
  });
  listEl.classList.add("show");
}

function getAddressIcon(type) {
  if ([ "hotel", "motel", "hostel", "guest_house", "chalet" ].includes(type)) return "🏨";
  if ([ "restaurant", "fast_food", "cafe", "bar", "food_court" ].includes(type)) return "🍽️";
  if ([ "shop", "mall", "supermarket", "department_store", "clothes" ].includes(type)) return "🛍️";
  if ([ "attraction", "theme_park", "museum", "zoo", "amusement_park" ].includes(type)) return "🎡";
  if ([ "airport", "aerodrome" ].includes(type)) return "✈️";
  if ([ "house", "residential", "apartments", "detached" ].includes(type)) return "🏠";
  return "📍";
}

function escHtml(s) {
  return String(s).replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;");
}

let hotelAcItems = [];

function routeHotelOverrideKey() {
  const uid = window._routeUid;
  const profile = localStorage.getItem("perfilActivoId") || "default";
  const tripId = uid ? window.TripContext.active(uid, profile) : "orlando";
  return `taxusa_hotel_addr::${profile}::${tripId}`;
}

function onHotelInput(val) {
  clearTimeout(hotelAcTimer);
  hotelFocusedIdx = -1;
  const spinner = document.getElementById("hotel-spinner");
  const listEl = document.getElementById("hotel-ac");
  localStorage.setItem(routeHotelOverrideKey(), val);
  if (!val || val.length < 3) {
    listEl.classList.remove("show");
    hotelAcItems = [];
    return;
  }
  spinner.style.display = "block";
  hotelAcTimer = setTimeout(async () => {
    hotelAcItems = await searchAddress(val);
    spinner.style.display = "none";
    renderAcList(listEl, hotelAcItems, item => {
      document.getElementById("hotel-input").value = item.address;
      localStorage.setItem(routeHotelOverrideKey(), item.address);
      listEl.classList.remove("show");
    }, hotelFocusedIdx);
  }, 450);
}

function onHotelKey(e) {
  const listEl = document.getElementById("hotel-ac");
  const items = listEl.querySelectorAll(".autocomplete-item");
  if (!listEl.classList.contains("show") || !items.length) return;
  if (e.key === "ArrowDown") {
    e.preventDefault();
    hotelFocusedIdx = Math.min(hotelFocusedIdx + 1, items.length - 1);
    items.forEach((el, i) => el.classList.toggle("focused", i === hotelFocusedIdx));
  } else if (e.key === "ArrowUp") {
    e.preventDefault();
    hotelFocusedIdx = Math.max(hotelFocusedIdx - 1, 0);
    items.forEach((el, i) => el.classList.toggle("focused", i === hotelFocusedIdx));
  } else if (e.key === "Enter" && hotelFocusedIdx >= 0) {
    e.preventDefault();
    if (hotelAcItems[hotelFocusedIdx]) {
      document.getElementById("hotel-input").value = hotelAcItems[hotelFocusedIdx].address;
      listEl.classList.remove("show");
    }
  } else if (e.key === "Escape") {
    listEl.classList.remove("show");
  }
}

let manualAcItems = [];

function onManualUrlInput(val) {
  clearTimeout(manualAcTimer);
  manualFocusedIdx = -1;
  const spinner = document.getElementById("manual-spinner");
  const listEl = document.getElementById("manual-ac");
  if (!val || val.length < 3 || val.startsWith("http")) {
    listEl.classList.remove("show");
    manualAcItems = [];
    return;
  }
  spinner.style.display = "block";
  manualAcTimer = setTimeout(async () => {
    manualAcItems = await searchAddress(val);
    spinner.style.display = "none";
    renderAcList(listEl, manualAcItems, item => {
      document.getElementById("manual-url").value = item.mapsUrl;
      const nameEl = document.getElementById("manual-name");
      if (!nameEl.value) nameEl.value = item.name;
      listEl.classList.remove("show");
    }, manualFocusedIdx);
  }, 350);
}

function onManualUrlKey(e) {
  const listEl = document.getElementById("manual-ac");
  const items = listEl.querySelectorAll(".autocomplete-item");
  if (!listEl.classList.contains("show") || !items.length) return;
  if (e.key === "ArrowDown") {
    e.preventDefault();
    manualFocusedIdx = Math.min(manualFocusedIdx + 1, items.length - 1);
    items.forEach((el, i) => el.classList.toggle("focused", i === manualFocusedIdx));
  } else if (e.key === "ArrowUp") {
    e.preventDefault();
    manualFocusedIdx = Math.max(manualFocusedIdx - 1, 0);
    items.forEach((el, i) => el.classList.toggle("focused", i === manualFocusedIdx));
  } else if (e.key === "Enter" && manualFocusedIdx >= 0) {
    e.preventDefault();
    if (manualAcItems[manualFocusedIdx]) {
      const item = manualAcItems[manualFocusedIdx];
      document.getElementById("manual-url").value = item.mapsUrl;
      const nameEl = document.getElementById("manual-name");
      if (!nameEl.value) nameEl.value = item.name;
      listEl.classList.remove("show");
    }
  } else if (e.key === "Escape") {
    listEl.classList.remove("show");
  }
}

document.addEventListener("click", e => {
  if (!document.getElementById("hotel-ac").contains(e.target) && e.target !== document.getElementById("hotel-input")) {
    document.getElementById("hotel-ac").classList.remove("show");
  }
  if (!document.getElementById("manual-ac").contains(e.target) && e.target !== document.getElementById("manual-url")) {
    document.getElementById("manual-ac").classList.remove("show");
  }
});

function parseLinks() {
  const raw = document.getElementById("links-input").value.trim();
  if (!raw) return;
  const lines = raw.split("\n").map(l => l.trim()).filter(Boolean);
  let added = 0;
  lines.forEach(url => {
    if (!url.startsWith("http")) return;
    let name = "Parada " + (stops.length + 1);
    const placeMatch = url.match(/place\/([^/]+)/);
    if (placeMatch) name = decodeURIComponent(placeMatch[1].replace(/\+/g, " "));
    stops.push({
      name: name,
      desc: "",
      url: url
    });
    added++;
  });
  document.getElementById("links-input").value = "";
  renderStops();
  showToast(addedToastMsg(added));
}

function handleCSV(input) {
  const file = input.files[0];
  if (!file) return;
  const reader = new FileReader;
  reader.onload = e => {
    document.getElementById("csv-text").value = e.target.result;
    parseCSV();
  };
  reader.readAsText(file);
}

function parseCSV() {
  const raw = document.getElementById("csv-text").value.trim();
  if (!raw) return;
  const lines = raw.split("\n").map(l => l.trim()).filter(Boolean);
  let added = 0;
  lines.forEach(line => {
    if (line.toLowerCase().startsWith("nombre") || line.toLowerCase().startsWith("name")) return;
    const cols = line.split(",").map(c => c.trim().replace(/^"|"$/g, ""));
    const name = cols[0] || "Parada " + (stops.length + 1);
    const desc = cols[1] || "";
    const url = cols[2] || "";
    if (name) {
      stops.push({
        name: name,
        desc: desc,
        url: url
      });
      added++;
    }
  });
  document.getElementById("csv-text").value = "";
  renderStops();
  showToast(addedToastMsg(added));
}

function addManual() {
  const name = document.getElementById("manual-name").value.trim();
  if (!name) {
    showToast("⚠️ " + L3("Escribí un nombre", "Enter a name", "Digite um nome"));
    return;
  }
  const desc = document.getElementById("manual-desc").value.trim();
  const url = document.getElementById("manual-url").value.trim();
  stops.push({
    name: name,
    desc: desc,
    url: url
  });
  document.getElementById("manual-name").value = "";
  document.getElementById("manual-desc").value = "";
  document.getElementById("manual-url").value = "";
  document.getElementById("manual-ac").classList.remove("show");
  renderStops();
  showToast("✅ " + L3("Parada agregada", "Stop added", "Parada adicionada"));
}

function renderStops() {
  const list = document.getElementById("stops-list");
  const empty = document.getElementById("stops-empty");
  const acts = document.getElementById("stops-actions");
  const genBtn = document.getElementById("btn-gen");
  list.innerHTML = "";
  empty.style.display = stops.length ? "none" : "block";
  acts.style.display = stops.length ? "flex" : "none";
  genBtn.disabled = stops.length === 0;
  stops.forEach((s, i) => {
    const row = document.createElement("div");
    row.className = "stop-row";
    row.innerHTML = `\n      <div class="stop-row-num">${i + 1}</div>\n      <div class="stop-row-body">\n        <div class="stop-row-name">${esc(s.name)}</div>\n        ${s.desc ? `<div class="stop-row-addr">${esc(s.desc)}</div>` : ""}\n        ${s.url ? `<div class="stop-row-addr" style="color:var(--primary)">${s.url.slice(0, 45)}…</div>` : ""}\n      </div>\n      <button class="stop-row-del" onclick="removeStop(${i})" aria-label="Eliminar parada">✕</button>`;
    list.appendChild(row);
  });
}

function removeStop(i) {
  stops.splice(i, 1);
  renderStops();
}

function clearStops() {
  stops = [];
  renderStops();
}

const dz = document.getElementById("drop-zone");

dz.addEventListener("dragover", e => {
  e.preventDefault();
  dz.classList.add("drag");
});

dz.addEventListener("dragleave", () => dz.classList.remove("drag"));

dz.addEventListener("drop", e => {
  e.preventDefault();
  dz.classList.remove("drag");
  const file = e.dataTransfer.files[0];
  if (!file) return;
  const reader = new FileReader;
  reader.onload = ev => {
    document.getElementById("csv-text").value = ev.target.result;
    parseCSV();
  };
  reader.readAsText(file);
});

async function generateRoute() {
  if (!stops.length) return;
  const hotel = document.getElementById("hotel-input").value.trim() || "Tu alojamiento";
  const dateVal = document.getElementById("start-date").value;
  const lang = localStorage.getItem("appLang") || "es";
  const dayWord = {
    es: "Día",
    en: "Day",
    pt: "Dia"
  }[lang] || "Día";
  const btn = document.getElementById("btn-gen");
  const originalHTML = btn.innerHTML;
  btn.disabled = true;
  btn.innerHTML = '<div class="spinner"></div><span>' + {
    es: "Optimizando ruta con IA…",
    en: "Optimizing route with AI…",
    pt: "Otimizando rota com IA…"
  }[lang] + "</span>";
  let orderedStops = stops;
  try {
    const stopsPayload = stops.map((s, i) => ({
      index: i,
      name: s.name,
      desc: s.desc || "",
      url: s.url || ""
    }));
    const systemPrompt = `You are a travel route optimization expert with real, detailed knowledge of Central Florida / Orlando geography — including the different areas/clusters: Walt Disney World & Lake Buena Vista, Universal Orlando Resort & International Drive, Kissimmee, downtown Orlando, Winter Garden, Winter Haven, and Cape Canaveral/Kennedy Space Center. Your ONLY task is to return a valid JSON array.\n\nGiven a list of stops (places to visit) and a starting point (hotel), group them into ${days} day(s) so the resulting itinerary is realistic and efficient, not just numerically balanced.\n\nRules:\n- Return ONLY a JSON array of arrays of original stop indexes (0-based), no explanation, no markdown, no backticks.\n- Each inner array = one day's stops, in optimal visit order for that day (minimizing backtracking).\n- Every stop index must appear exactly once across all days.\n- FULL-DAY ANCHORS: major theme parks (e.g. Magic Kingdom, EPCOT, Hollywood Studios, Animal Kingdom, Universal Studios, Islands of Adventure, Epic Universe, Volcano Bay, SeaWorld, Legoland, Busch Gardens, and similar large parks) each realistically take a FULL day by themselves. Never put two of these full-day anchors on the same day — each one gets its own day — unless there are strictly more anchors than available days, in which case distribute them as evenly as possible.\n- Smaller stops (outlets, malls, museums, short attractions, parks, tours, restaurants) CAN be combined 2-3 per day, but only if they are genuinely in the same or adjacent area. Do NOT mix stops from different areas just because they fit numerically — e.g. don't combine something in the Disney/Lake Buena Vista area with something on International Drive/Universal, and don't combine downtown Orlando with Kissimmee, unless there is no other reasonable option.\n- Attractions clearly far from the main Orlando area (e.g. Kennedy Space Center, Legoland in Winter Haven) should be alone on their day — the drive there and back already fills the day.\n- Use your own knowledge of these specific places and their real locations to judge proximity — don't just pattern-match on city names in the address text.\n- If a stop's location is unclear or missing, use its name/description to infer the area as best you can; only fall back to the original order if truly no signal exists.\n- Spread stops as evenly as possible across days ONLY after applying the rules above — realism comes first, balance second.\n\nExample output for 3 stops, 2 days: [[0,2],[1]]`;
    const userMsg = `Hotel/Starting point: ${hotel}\nNumber of days: ${days}\nStops to organize:\n${JSON.stringify(stopsPayload, null, 2)}\n\nReturn ONLY the JSON array of arrays of indexes.`;
    const res = await window.taxflyWorker({
      type: "optimize_route",
      messages: [ {
        role: "system",
        content: systemPrompt
      }, {
        role: "user",
        content: userMsg
      } ],
      max_tokens: 2e3
    });
    if (res.ok) {
      const data = await res.json();
      const raw = data.choices?.[0]?.message?.content || "";
      const jsonMatch = raw.match(/\[[\s\S]*\]/);
      if (jsonMatch) {
        const parsed = JSON.parse(jsonMatch[0]);
        const allIndexes = parsed.flat();
        const valid = Array.isArray(parsed) && parsed.every(day => Array.isArray(day)) && allIndexes.length === stops.length && allIndexes.every(i => typeof i === "number" && i >= 0 && i < stops.length);
        if (valid) {
          const dayData = [];
          parsed.forEach((dayIndexes, d) => {
            if (!dayIndexes.length) return;
            const chunk = dayIndexes.map(i => stops[i]);
            let label = `${dayWord} ${d + 1}`;
            let shortLabel = `${dayWord} ${d + 1}`;
            let dateLabel = "";
            if (dateVal) {
              const date = new Date(dateVal + "T12:00:00");
              date.setDate(date.getDate() + d);
              const locale = lang === "pt" ? "pt-BR" : lang === "en" ? "en-US" : "es-AR";
              const shortDate = date.toLocaleDateString(locale, {
                day: "2-digit",
                month: "2-digit"
              });
              const weekday = date.toLocaleDateString(locale, {
                weekday: "short"
              });
              label = `${dayWord} ${d + 1} — ${weekday} ${shortDate}`;
              shortLabel = `${dayWord} ${d + 1}`;
              dateLabel = `${weekday} ${shortDate}`;
            }
            dayData.push({
              label: label,
              shortLabel: shortLabel,
              dateLabel: dateLabel,
              stops: chunk
            });
          });
          routeData = {
            hotel: hotel,
            dayData: dayData
          };
          visited = {};
          activeDay = 0;
          saveVisited();
          btn.innerHTML = originalHTML;
          btn.disabled = stops.length === 0;
          document.getElementById("builder-card").style.display = "none";
          document.getElementById("ruta-result").style.display = "block";
          renderResult();
          window.scrollTo({
            top: 0,
            behavior: "smooth"
          });
          showToast("✨ " + {
            es: "Ruta optimizada con IA",
            en: "Route optimized with AI",
            pt: "Rota otimizada com IA"
          }[lang]);
          return;
        }
      }
    }
  } catch (e) {}
  btn.innerHTML = originalHTML;
  btn.disabled = stops.length === 0;
  const perDay = Math.ceil(stops.length / days);
  const dayDataFallback = [];
  for (let d = 0; d < days; d++) {
    const chunk = stops.slice(d * perDay, (d + 1) * perDay);
    if (!chunk.length) continue;
    let label = `${dayWord} ${d + 1}`;
    let shortLabel = `${dayWord} ${d + 1}`;
    let dateLabel = "";
    if (dateVal) {
      const date = new Date(dateVal + "T12:00:00");
      date.setDate(date.getDate() + d);
      const locale = lang === "pt" ? "pt-BR" : lang === "en" ? "en-US" : "es-AR";
      const shortDate = date.toLocaleDateString(locale, {
        day: "2-digit",
        month: "2-digit"
      });
      const weekday = date.toLocaleDateString(locale, {
        weekday: "short"
      });
      label = `${dayWord} ${d + 1} — ${weekday} ${shortDate}`;
      shortLabel = `${dayWord} ${d + 1}`;
      dateLabel = `${weekday} ${shortDate}`;
    }
    dayDataFallback.push({
      label: label,
      shortLabel: shortLabel,
      dateLabel: dateLabel,
      stops: chunk
    });
  }
  routeData = {
    hotel: hotel,
    dayData: dayDataFallback
  };
  visited = {};
  activeDay = 0;
  saveVisited();
  document.getElementById("builder-card").style.display = "none";
  document.getElementById("ruta-result").style.display = "block";
  renderResult();
  window.scrollTo({
    top: 0,
    behavior: "smooth"
  });
  showToast("⚠️ " + {
    es: "IA no disponible, ruta generada sin optimizar",
    en: "AI unavailable, route generated without optimization",
    pt: "IA indisponível, rota gerada sem otimização"
  }[lang]);
}

let activeDay = 0;

function saveRouteToTrip() {
  if (!routeData?.dayData?.length || !window._routeUid) return;
  const profile = localStorage.getItem("perfilActivoId");
  const tripId = window.TripContext.active(window._routeUid, profile);
  sessionStorage.setItem("taxfly-route-import", JSON.stringify({
    tripId, profile, startDate: document.getElementById("start-date").value,
    days: routeData.dayData.map(d => ({ name: d.label, stops: d.stops.map(s => ({
      name: s.name, note: s.desc || "", url: s.url || ""
    })) }))
  }));
  location.href = "planificacion.html?section=parques";
}

function switchDay(d) {
  activeDay = d;
  document.querySelectorAll(".day-tab").forEach((t, i) => t.classList.toggle("active", i === d));
  document.querySelectorAll(".day-panel").forEach((p, i) => p.classList.toggle("active", i === d));
  document.querySelectorAll(".day-nav-btn").forEach((b, i) => b.classList.toggle("active", i === d));
  window.scrollTo({
    top: 0,
    behavior: "smooth"
  });
}

function buildTabs() {
  const tabsEl = document.getElementById("day-tabs");
  const navEl = document.getElementById("day-bottom-nav");
  if (!tabsEl || !navEl) return;
  tabsEl.innerHTML = "";
  navEl.innerHTML = "";
  routeData.dayData.forEach((day, i) => {
    const tab = document.createElement("button");
    tab.className = "day-tab" + (i === activeDay ? " active" : "");
    tab.textContent = day.shortLabel || day.label;
    tab.onclick = () => switchDay(i);
    tabsEl.appendChild(tab);
    const btn = document.createElement("button");
    btn.className = "day-nav-btn" + (i === activeDay ? " active" : "");
    btn.id = "day-nav-" + i;
    const done = routeData.dayData[i].stops.filter((_, si) => visited[`${i}-${si}`]).length;
    const total = routeData.dayData[i].stops.length;
    const hasProgress = done > 0 && done < total;
    const allDone = done === total && total > 0;
    const dot = hasProgress ? '<span class="dnb-dot"></span>' : allDone ? " ✓" : "";
    btn.innerHTML = (day.shortLabel || "Día " + (i + 1)) + dot + (day.dateLabel ? `<span class="dnb-date">${day.dateLabel}</span>` : "");
    btn.onclick = () => switchDay(i);
    navEl.appendChild(btn);
  });
  navEl.classList.add("show");
}

function renderResult() {
  const out = document.getElementById("days-output");
  out.innerHTML = "";
  let total = 0, done = 0;
  routeData.dayData.forEach((day, di) => {
    total += day.stops.length;
    const dayDone = day.stops.filter((_, si) => visited[`${di}-${si}`]).length;
    done += dayDone;
    const pct = Math.round(dayDone / day.stops.length * 100);
    const allDone = dayDone === day.stops.length && day.stops.length > 0;
    const panel = document.createElement("div");
    panel.className = "day-panel" + (di === activeDay ? " active" : "");
    panel.id = "day-panel-" + di;
    let html = `\n      <a class="hotel-bar-result" href="https://www.google.com/maps/search/?api=1&query=${encodeURIComponent(routeData.hotel)}" target="_blank">\n        <div class="hotel-bar-icon">🏠</div>\n        <div class="hotel-bar-info">\n          <div class="hotel-bar-label">Punto de partida</div>\n          <div class="hotel-bar-addr">${escHtml(routeData.hotel)}</div>\n        </div>\n        <div class="hotel-bar-arrow">↗</div>\n      </a>\n      <div class="day-prog-wrap">\n        <div class="day-prog-meta">\n          <div class="day-prog-stats">\n            <div class="dp-stat"><div class="dp-val ${dayDone > 0 ? "accent" : ""}">${dayDone}</div><div class="dp-lbl">visit.</div></div>\n            <div class="dp-stat"><div class="dp-val">${day.stops.length}</div><div class="dp-lbl">paradas</div></div>\n            <div class="dp-stat"><div class="dp-val ${pct === 100 ? "accent" : ""}">${pct}%</div><div class="dp-lbl">hecho</div></div>\n          </div>\n          <button class="btn-reset" onclick="resetDay(${di})">↺ reiniciar</button>\n        </div>\n        <div class="day-prog-bar-bg"><div class="day-prog-bar-fill" style="width:${pct}%"></div></div>\n      </div>`;
    if (allDone) {
      html += `<div class="all-done-state show">\n        <div class="all-done-emoji">🎉</div>\n        <div class="all-done-title">¡Día completado!</div>\n        <div class="all-done-sub">Visitaste las ${day.stops.length} paradas del día.</div>\n      </div>`;
    }
    day.stops.forEach((s, si) => {
      const isV = !!visited[`${di}-${si}`];
      const mapsIcon = `<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M12 2C8.13 2 5 5.13 5 9c0 5.25 7 13 7 13s7-7.75 7-13c0-3.87-3.13-7-7-7z"/><circle cx="12" cy="9" r="2.5"/></svg>`;
      html += `\n        <div class="ruta-stop${isV ? " visited" : ""}" onclick="toggleVisit(${di},${si})" style="animation-delay:${si * .03}s">\n          <div class="rs-num">${isV ? "✓" : si + 1}</div>\n          <div class="rs-body">\n            <div class="rs-name">${escHtml(s.name)}</div>\n            ${s.desc ? `<div class="rs-desc">${escHtml(s.desc)}</div>` : ""}\n            <div class="rs-footer">\n              <span></span>\n              ${s.url ? `<a class="rs-maps" href="${s.url}" onclick="event.stopPropagation()" target="_blank">${mapsIcon} Maps</a>` : ""}\n            </div>\n          </div>\n        </div>`;
    });
    panel.innerHTML = html;
    out.appendChild(panel);
  });
  const pct = total ? Math.round(done / total * 100) : 0;
  document.getElementById("gp-done").textContent = done;
  document.getElementById("gp-total").textContent = total;
  document.getElementById("gp-bar").style.width = pct + "%";
  buildTabs();
}

function toggleVisit(di, si) {
  const key = `${di}-${si}`;
  if (visited[key]) delete visited[key]; else visited[key] = 1;
  saveVisited();
  renderResult();
  const day = routeData.dayData[di];
  const allDone = day.stops.every((_, s) => visited[`${di}-${s}`]);
  if (allDone) launchConfetti();
}

function resetDay(di) {
  routeData.dayData[di].stops.forEach((_, si) => {
    delete visited[`${di}-${si}`];
  });
  saveVisited();
  renderResult();
}

function saveVisited() {
  try {
    localStorage.setItem(VISITED_KEY, JSON.stringify(visited));
  } catch (e) {}
}

function resetVisited() {
  visited = {};
  saveVisited();
  renderResult();
}

function resetAll() {
  stops = [];
  routeData = null;
  visited = {};
  activeDay = 0;
  saveVisited();
  renderStops();
  document.getElementById("builder-card").style.display = "block";
  document.getElementById("ruta-result").style.display = "none";
  document.getElementById("day-bottom-nav").classList.remove("show");
  document.getElementById("hotel-input").value = "";
  localStorage.removeItem(routeHotelOverrideKey());
  document.getElementById("start-date").value = "";
  days = 3;
  document.getElementById("days-count").textContent = "3";
}

function routeMapBootstrap() {
  document.addEventListener('click', function(e) {
    var link = e.target.closest('a.s-maps,a.hotel-bar');
    if (!link) return;
    e.preventDefault();
    e.stopPropagation();
    var google = link.href;
    var query = link.closest('.stop,.hotel-bar').querySelector('.s-name,.h-addr')?.textContent?.trim() || google;
    if (/iPad|iPhone|iPod/i.test(navigator.userAgent) || (navigator.platform === 'MacIntel' && navigator.maxTouchPoints > 1)) {
      var d = document.getElementById('map-choice-route');
      if (!d) {
        d = document.createElement('dialog'); d.id = 'map-choice-route';
        d.style.cssText = 'background:#1e293b;color:white;border:1px solid #64748b;border-radius:15px;padding:20px;font:600 15px system-ui';
        d.innerHTML = '<strong>Abrir en Maps</strong><p><a data-apple>Apple Maps</a></p><p><a data-google>Google Maps</a></p><button>Cancelar</button>';
        d.querySelectorAll('a,button').forEach(function(el) { el.style.cssText = 'display:block;padding:10px;color:white;background:#273549;border:1px solid #64748b;border-radius:8px;text-align:center;text-decoration:none'; el.onclick = function() { d.close(); }; });
        document.body.appendChild(d);
      }
      d.querySelector('[data-apple]').href = 'https://maps.apple.com/?q=' + encodeURIComponent(query);
      d.querySelector('[data-google]').href = google;
      d.showModal();
    } else if (/Android/i.test(navigator.userAgent)) location.href = google;
    else window.open(google, '_blank', 'noopener,noreferrer');
  }, true);
}

function downloadHTML() {
  if (!routeData) return;
  const H = JSON.stringify(routeData.hotel);
  const D = JSON.stringify(routeData.dayData);
  const html = `<!DOCTYPE html>\n<html lang="es">\n<head>\n<meta charset="UTF-8">\n<meta name="viewport" content="width=device-width,initial-scale=1">\n<meta name="apple-mobile-web-app-capable" content="yes">\n<title>Mi Ruta TaxUSA</title>\n<link href="https://fonts.googleapis.com/css2?family=DM+Sans:wght@400;600;700;800;900&display=swap" rel="stylesheet">\n<style>\n:root{--bg:#f1f5f9;--surface:#fff;--surface2:#f8fafc;--border:#e2e8f0;--text:#0f172a;--sub:#64748b;--dim:#94a3b8;--primary:#2563eb;--success:#10b981;--accent:#7c3aed;--radius:14px;}\n@media(prefers-color-scheme:dark){:root{--bg:#0f172a;--surface:#1e293b;--surface2:#273549;--border:#334155;--text:#f1f5f9;--sub:#94a3b8;--dim:#64748b;}}\n*{box-sizing:border-box;margin:0;padding:0;-webkit-tap-highlight-color:transparent;}\nbody{font-family:'DM Sans',system-ui,sans-serif;background:var(--bg);color:var(--text);min-height:100vh;padding:16px 16px 100px;}\n.wrap{max-width:460px;margin:0 auto;}\n.title{font-size:1.2rem;font-weight:900;color:var(--primary);margin-bottom:2px;}\n.subtitle{font-size:.72rem;color:var(--sub);margin-bottom:14px;}\n.prog-card{background:var(--surface);border:1px solid var(--border);border-radius:var(--radius);padding:14px;margin-bottom:14px;display:flex;align-items:center;gap:14px;}\n.gp-stat{text-align:center;flex:1;}.gp-val{font-size:1.4rem;font-weight:900;color:var(--primary);}.gp-lbl{font-size:.55rem;font-weight:700;color:var(--dim);text-transform:uppercase;letter-spacing:.5px;}\n.gp-bw{flex:2;}.gp-row{display:flex;justify-content:space-between;margin-bottom:4px;}.gp-lbl2{font-size:.6rem;font-weight:700;color:var(--dim);}.reset-btn{background:none;border:none;color:var(--dim);font-size:.65rem;cursor:pointer;font-family:inherit;padding:0;}\n.gp-bg{height:6px;background:var(--border);border-radius:3px;overflow:hidden;}.gp-fill{height:100%;background:linear-gradient(90deg,var(--primary),var(--accent));border-radius:3px;transition:width .4s;}\n.tabs-wrap{overflow-x:auto;scrollbar-width:none;margin-bottom:12px;}.tabs-wrap::-webkit-scrollbar{display:none;}\n.tabs{display:flex;gap:6px;padding-bottom:2px;}\n.tab{flex-shrink:0;padding:8px 16px;border-radius:999px;border:1.5px solid var(--border);background:transparent;color:var(--sub);font-family:inherit;font-size:.72rem;font-weight:700;cursor:pointer;transition:all .2s;white-space:nowrap;}\n.tab.active{background:var(--primary);color:#fff;border-color:var(--primary);}\n.panel{display:none;}.panel.active{display:block;}\n.hotel-bar{display:flex;align-items:center;gap:10px;background:var(--surface2);border:1px solid var(--border);border-radius:12px;padding:12px 14px;margin-bottom:10px;text-decoration:none;}\n.h-icon{width:30px;height:30px;background:rgba(37,99,235,.1);border-radius:8px;display:flex;align-items:center;justify-content:center;font-size:14px;flex-shrink:0;}\n.h-info{flex:1;min-width:0;}.h-lbl{font-size:.55rem;color:var(--primary);font-weight:800;letter-spacing:.8px;text-transform:uppercase;margin-bottom:2px;}.h-addr{font-size:.72rem;color:var(--sub);white-space:nowrap;overflow:hidden;text-overflow:ellipsis;}\n.h-arr{color:var(--dim);font-size:.8rem;}\n.dp-wrap{margin-bottom:12px;}.dp-row{display:flex;justify-content:space-between;align-items:center;margin-bottom:6px;}.dp-stats{display:flex;gap:12px;}.dp-s{text-align:center;}.dp-v{font-size:1rem;font-weight:900;color:var(--text);}.dp-v.ac{color:var(--primary);}.dp-l{font-size:.55rem;color:var(--dim);font-weight:600;text-transform:uppercase;}\n.dp-bg{height:3px;background:var(--border);border-radius:2px;overflow:hidden;}.dp-fill{height:100%;background:linear-gradient(90deg,var(--primary),var(--success));border-radius:2px;transition:width .4s;}\n.stop{display:flex;align-items:flex-start;gap:12px;background:var(--surface);border:1px solid var(--border);border-radius:12px;padding:14px;margin-bottom:8px;cursor:pointer;transition:all .2s;position:relative;overflow:hidden;}\n.stop::before{content:'';position:absolute;left:0;top:0;bottom:0;width:3px;background:transparent;transition:background .2s;}\n.stop.v{background:var(--surface2);}.stop.v::before{background:var(--success);}\n.stop:active{transform:scale(.98);}\n.s-num{width:28px;height:28px;border-radius:50%;border:1.5px solid var(--border);display:flex;align-items:center;justify-content:center;font-size:.7rem;font-weight:800;color:var(--sub);flex-shrink:0;transition:all .15s;}\n.stop.v .s-num{background:rgba(16,185,129,.12);border-color:var(--success);color:var(--success);}\n.s-body{flex:1;min-width:0;}.s-name{font-size:.88rem;font-weight:700;color:var(--text);margin-bottom:4px;line-height:1.3;}.stop.v .s-name{text-decoration:line-through;color:var(--dim);}\n.s-desc{font-size:.72rem;color:var(--sub);line-height:1.5;margin-bottom:8px;}.stop.v .s-desc{opacity:.5;}\n.s-foot{display:flex;align-items:center;justify-content:flex-end;}\na{text-decoration:none !important;}\n.s-maps{display:flex;align-items:center;gap:5px;background:var(--surface2);border:1px solid var(--border);border-radius:999px;padding:5px 10px;color:var(--sub);font-size:.68rem;font-weight:600;text-decoration:none;}\n.bnav{position:fixed;bottom:0;left:0;right:0;background:var(--surface);border-top:1px solid var(--border);display:flex;padding:8px 12px calc(8px + env(safe-area-inset-bottom));gap:6px;}\n.bn{flex:1;padding:10px 6px;border-radius:12px;border:1.5px solid var(--border);background:transparent;color:var(--sub);font-family:inherit;font-size:.65rem;font-weight:700;cursor:pointer;transition:all .2s;text-align:center;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;}\n.bn.active{background:var(--primary);color:#fff;border-color:var(--primary);}\n.bn-date{font-size:.55rem;font-weight:500;display:block;margin-top:2px;opacity:.7;}\n.cw{position:fixed;inset:0;pointer-events:none;z-index:9999;overflow:hidden;}\n.cp{position:absolute;top:-20px;animation:cf linear forwards;}\n@keyframes cf{to{transform:translateY(110vh) rotate(720deg);opacity:0;}}\n.all-done{text-align:center;padding:28px 0;display:none;}\n.all-done.show{display:block;}\n.ad-emoji{font-size:2.5rem;margin-bottom:8px;}.ad-title{font-size:1rem;font-weight:900;color:var(--primary);margin-bottom:4px;}.ad-sub{font-size:.78rem;color:var(--sub);}\n</style>\n</head>\n<body>\n<div class="cw" id="cw"></div>\n<div class="wrap">\n  <div class="title">🗺️ Mi Ruta TaxUSA</div>\n  <div class="subtitle">Tocá cada parada para marcarla como visitada</div>\n  <div class="prog-card">\n    <div class="gp-stat"><div class="gp-val" id="gd">0</div><div class="gp-lbl">visitadas</div></div>\n    <div class="gp-bw">\n      <div class="gp-row"><span class="gp-lbl2">PROGRESO TOTAL</span><button class="reset-btn" onclick="resetAll()">reiniciar</button></div>\n      <div class="gp-bg"><div class="gp-fill" id="gb" style="width:0%"></div></div>\n    </div>\n    <div class="gp-stat"><div class="gp-val" id="gt">0</div><div class="gp-lbl">paradas</div></div>\n  </div>\n  <div class="tabs-wrap"><div class="tabs" id="tabs"></div></div>\n  <div id="panels"></div>\n</div>\n<nav class="bnav" id="bnav"></nav>\n<script>\nvar H=${H};\nvar D=${D};\nvar AD=0;\nvar V={};try{V=JSON.parse(localStorage.getItem('rt_v')||'{}')}catch(e){}\nfunction save(){try{localStorage.setItem('rt_v',JSON.stringify(V))}catch(e){}}\nfunction esc(s){return String(s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');}\nfunction confetti(){var w=document.getElementById('cw');var c=['#2563eb','#f59e0b','#10b981','#f1f5f9','#ef4444','#7c3aed'];for(var i=0;i<60;i++){var el=document.createElement('div');el.className='cp';el.style.cssText='left:'+Math.random()*100+'%;width:'+(5+Math.random()*8)+'px;height:'+(5+Math.random()*8)+'px;background:'+c[Math.floor(Math.random()*c.length)]+';border-radius:'+(Math.random()>.5?'50%':'2px')+';animation-duration:'+(1.5+Math.random()*2)+'s;animation-delay:'+(Math.random()*.5)+'s';w.appendChild(el);setTimeout((function(x){return function(){x.remove()}})(el),4000)}}\nfunction toggle(di,si){var k=di+'-'+si;if(V[k])delete V[k];else V[k]=1;save();render();var day=D[di];if(day.stops.every(function(_,s){return V[di+'-'+s]})){setTimeout(confetti,200)}}\nfunction resetDay(di){D[di].stops.forEach(function(_,si){delete V[di+'-'+si]});save();render();}\nfunction resetAll(){V={};save();render();}\nfunction switchDay(d){AD=d;document.querySelectorAll('.tab').forEach(function(t,i){t.classList.toggle('active',i===d)});document.querySelectorAll('.panel').forEach(function(p,i){p.classList.toggle('active',i===d)});document.querySelectorAll('.bn').forEach(function(b,i){b.classList.toggle('active',i===d)});window.scrollTo({top:0,behavior:'smooth'});}\nfunction render(){\n  var tabs=document.getElementById('tabs');var panels=document.getElementById('panels');var bnav=document.getElementById('bnav');\n  tabs.innerHTML='';panels.innerHTML='';bnav.innerHTML='';\n  var total=0,done=0;\n  D.forEach(function(day,di){\n    total+=day.stops.length;\n    var dd=day.stops.filter(function(_,si){return V[di+'-'+si]}).length;done+=dd;\n    var pct=day.stops.length?Math.round(dd/day.stops.length*100):0;\n    var allDone=dd===day.stops.length&&day.stops.length>0;\n    // Tab\n    var tab=document.createElement('button');tab.className='tab'+(di===AD?' active':'');tab.textContent=day.shortLabel||day.label;tab.onclick=(function(i){return function(){switchDay(i)}})(di);tabs.appendChild(tab);\n    // Nav\n    var bn=document.createElement('button');bn.className='bn'+(di===AD?' active':'');\n    var dot=dd>0&&dd<day.stops.length?'<span style="display:inline-block;width:5px;height:5px;border-radius:50%;background:#10b981;margin-left:3px;vertical-align:middle;"></span>':allDone?' ✓':'';\n    bn.innerHTML=(day.shortLabel||('Día '+(di+1)))+dot+(day.dateLabel?'<span class="bn-date">'+day.dateLabel+'</span>':'');\n    bn.onclick=(function(i){return function(){switchDay(i)}})(di);bnav.appendChild(bn);\n    // Panel\n    var panel=document.createElement('div');panel.className='panel'+(di===AD?' active':'');\n    var html='<a class="hotel-bar" href="https://www.google.com/maps/search/?api=1&query='+encodeURIComponent(H)+'" target="_blank"><div class="h-icon">🏠</div><div class="h-info"><div class="h-lbl">Punto de partida</div><div class="h-addr">'+esc(H)+'</div></div><div class="h-arr">↗</div></a>';\n    html+='<div class="dp-wrap"><div class="dp-row"><div class="dp-stats"><div class="dp-s"><div class="dp-v'+(dd>0?' ac':'')+'">'+dd+'</div><div class="dp-l">visit.</div></div><div class="dp-s"><div class="dp-v">'+day.stops.length+'</div><div class="dp-l">paradas</div></div><div class="dp-s"><div class="dp-v'+(pct===100?' ac':'')+'">'+pct+'%</div><div class="dp-l">hecho</div></div></div><button class="reset-btn" onclick="resetDay('+di+')">↺ reiniciar</button></div><div class="dp-bg"><div class="dp-fill" id="dpf-'+di+'" style="width:'+pct+'%"></div></div></div>';\n    if(allDone){html+='<div class="all-done show"><div class="ad-emoji">🎉</div><div class="ad-title">¡Día completado!</div><div class="ad-sub">Visitaste las '+day.stops.length+' paradas del día.</div></div>';}\n    day.stops.forEach(function(s,si){var v=!!V[di+'-'+si];html+='<div class="stop'+(v?' v':'')+'" onclick="toggle('+di+','+si+')" style="animation-delay:'+(si*.03)+'s"><div class="s-num">'+(v?'✓':si+1)+'</div><div class="s-body"><div class="s-name">'+esc(s.name)+'</div>'+(s.desc?'<div class="s-desc">'+esc(s.desc)+'</div>':'')+'<div class="s-foot">'+(s.url?'<a class="s-maps" href="'+s.url+'" onclick="event.stopPropagation()" target="_blank">📍 Maps</a>':'')+'</div></div></div>';});\n    panel.innerHTML=html;panels.appendChild(panel);\n  });\n  var gPct=total?Math.round(done/total*100):0;\n  document.getElementById('gd').textContent=done;document.getElementById('gt').textContent=total;document.getElementById('gb').style.width=gPct+'%';\n}\nrender();\n<\/script>\n<script>(${routeMapBootstrap.toString()})()<\/script>
</body>\n</html>`;
  const blob = new Blob([ html ], {
    type: "text/html"
  });
  const a = document.createElement("a");
  a.href = URL.createObjectURL(blob);
  a.download = "mi-ruta-taxusa.html";
  a.click();
  showToast("⬇️ " + L3("Archivo descargado", "File downloaded", "Arquivo baixado"));
}

function launchConfetti() {
  const wrap = document.getElementById("confetti-wrap");
  const colors = [ "#2563eb", "#f59e0b", "#10b981", "#ef4444", "#7c3aed", "#f1f5f9" ];
  for (let i = 0; i < 55; i++) {
    const el = document.createElement("div");
    el.className = "confetti-p";
    el.style.cssText = `left:${Math.random() * 100}%;width:${5 + Math.random() * 8}px;height:${5 + Math.random() * 8}px;background:${colors[Math.floor(Math.random() * colors.length)]};border-radius:${Math.random() > .5 ? "50%" : "2px"};animation-duration:${1.5 + Math.random() * 2}s;animation-delay:${Math.random() * .4}s`;
    wrap.appendChild(el);
    setTimeout(() => el.remove(), 4e3);
  }
}

function L3(es, en, pt) {
  const l = localStorage.getItem("appLang") || "es";
  return l === "en" ? en : l === "pt" ? pt : es;
}
function addedToastMsg(added) {
  return "✅ " + L3(
    `${added} parada${added > 1 ? "s" : ""} agregada${added > 1 ? "s" : ""}`,
    `${added} stop${added > 1 ? "s" : ""} added`,
    `${added} parada${added > 1 ? "s" : ""} adicionada${added > 1 ? "s" : ""}`
  );
}
function showToast(msg) {
  if (window.tfToast) { window.tfToast(msg, { duration: 2800 }); return; }
  const t = document.getElementById("toast");
  t.textContent = msg;
  t.classList.add("show");
  setTimeout(() => t.classList.remove("show"), 2500);
}

renderStops();

document.addEventListener("DOMContentLoaded", () => {
  const foto = localStorage.getItem("perfilActivoFoto");
  if (foto) {
    const btn = document.getElementById("btnSettings");
    if (btn) {
      btn.style.backgroundImage = `url('${foto}')`;
      btn.innerText = "";
    }
  }
  const lang = localStorage.getItem("appLang") || "es";
  window.changeLanguage(lang);
  const inp = document.getElementById("hotel-input");
  if (inp) {
    const saved = localStorage.getItem(routeHotelOverrideKey());
    if (saved) inp.value = saved;
    inp.placeholder = HOTEL_PLACEHOLDERS[_phIdx];
  }
});
